import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/Books/02-SupplementaryArticles/Thinking/03-How-did-hackers-steal-your-lucky-money.html","title":"03-密码背后的较量：你真的安全吗？","lang":"zh-CN","frontmatter":{"title":"03-密码背后的较量：你真的安全吗？","icon":"read","date":"2025-04-25T22:24:48.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":false,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"watermark":{"width":200,"height":200,"content":"《编程启蒙：思维与代码》作者：黄家宝","opacity":0.5},"description":"在电影里，黑客往往神秘莫测：黑进银行账户转走别人的钱、入侵路边、家用摄像头监控某人、甚至闯入军事系统获取军事机密，一副“我无所不能”的样子。 但现实中的“黑客”远比你想象的更复杂。 首先，“黑客”这个词，其实源自英文的 hacker，它原本的意思是“酷爱钻研技术的人”，很多编程高手都以此自称。也就是说，并不是每个黑客都是坏人。相反，很多真正的黑客，正是...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"03-密码背后的较量：你真的安全吗？\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2025-04-25T22:24:48.000Z\\",\\"dateModified\\":\\"2025-05-07T11:44:53.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/Books/02-SupplementaryArticles/Thinking/03-How-did-hackers-steal-your-lucky-money.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"03-密码背后的较量：你真的安全吗？"}],["meta",{"property":"og:description","content":"在电影里，黑客往往神秘莫测：黑进银行账户转走别人的钱、入侵路边、家用摄像头监控某人、甚至闯入军事系统获取军事机密，一副“我无所不能”的样子。 但现实中的“黑客”远比你想象的更复杂。 首先，“黑客”这个词，其实源自英文的 hacker，它原本的意思是“酷爱钻研技术的人”，很多编程高手都以此自称。也就是说，并不是每个黑客都是坏人。相反，很多真正的黑客，正是..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-05-07T11:44:53.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-04-25T22:24:48.000Z"}],["meta",{"property":"article:modified_time","content":"2025-05-07T11:44:53.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1746618293000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":14,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"74434ca22b4dbb049c5d8cf6d6a63a10b07fd700","time":1746618293000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新侧边栏，添加目录项并禁用各章节的导航栏"},{"hash":"9c9b2ba2b8ef4cc1b61c10448101aa350e9450ee","time":1746617928000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新思维章节，添加水印信息并调整侧边栏内容"},{"hash":"9fe778ec384b68cfc405b291cf05475dbfed5c84","time":1746616663000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新"},{"hash":"32742c5a7b4409f9d8343e4a7f4a392536d11f6a","time":1746616274000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新思维补充文章"},{"hash":"78982cdd7701e9137da1888ef2955e8a1a3c3bac","time":1745628041000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"c4f57d302b2af9b6c027bfe770a6889156a181de","time":1745596251000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"77beae446697dc5e897aa12c9a42bb25e589c12e","time":1745596218000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"在文章中添加一张图片，并优化部分段落的连贯性"},{"hash":"9ba20a2768b348291a6e9a8653ab0ba566be592f","time":1745595939000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"f45cfa08005809431bb229c826a57fe77460e626","time":1745594308000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"3a296fb1bb050a6931bed646dee087ff73500518","time":1745591514000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"9ce3f18bd55b4496f61dc288cbe02cee98e4712d","time":1745590866000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft of \\"How did hackers steal your lucky money\\" article"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.21,"words":2463},"filePathRelative":"Books/02-SupplementaryArticles/Thinking/03-How-did-hackers-steal-your-lucky-money.md","excerpt":"<figure><figcaption></figcaption></figure>\\n<p>在电影里，黑客往往神秘莫测：黑进银行账户转走别人的钱、入侵路边、家用摄像头监控某人、甚至闯入军事系统获取军事机密，一副“我无所不能”的样子。</p>\\n<p>但现实中的“黑客”远比你想象的更复杂。</p>\\n<p>首先，“黑客”这个词，其实源自英文的 <strong>hacker</strong>，它原本的意思是“酷爱钻研技术的人”，很多编程高手都以此自称。也就是说，<strong>并不是每个黑客都是坏人</strong>。相反，很多真正的黑客，正是维护网络安全的幕后英雄。</p>\\n<p>那今天，我们就来聊一聊这个“神秘职业”的真面目，同时告诉你三条实用的“数字生活防身术”。</p>","autoDesc":true}`),a={name:`03-How-did-hackers-steal-your-lucky-money.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/image-20250425224347986-DqLvN4Vk.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>在电影里，黑客往往神秘莫测：黑进银行账户转走别人的钱、入侵路边、家用摄像头监控某人、甚至闯入军事系统获取军事机密，一副“我无所不能”的样子。</p><p>但现实中的“黑客”远比你想象的更复杂。</p><p>首先，“黑客”这个词，其实源自英文的 <strong>hacker</strong>，它原本的意思是“酷爱钻研技术的人”，很多编程高手都以此自称。也就是说，<strong>并不是每个黑客都是坏人</strong>。相反，很多真正的黑客，正是维护网络安全的幕后英雄。</p><p>那今天，我们就来聊一聊这个“神秘职业”的真面目，同时告诉你三条实用的“数字生活防身术”。</p><h2 id="_1-第一招-密码不止要长-还要难猜" tabindex="-1"><a class="header-anchor" href="#_1-第一招-密码不止要长-还要难猜"><span>1. 第一招：密码不止要长，还要难猜！</span></a></h2><figure><img src="/assets/image-20250425225223227-BI46GGCw.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你肯定知道，无论是银行、QQ、微信还是各种游戏、外卖软件，都有账号密码，这个账号就相当于是你的房间，密码就是你房间的钥匙。</p><figure><img src="/assets/image-20250425225400309-D3RZ_jBJ.png" alt="偷钱的黑客" tabindex="0" loading="lazy"><figcaption>偷钱的黑客</figcaption></figure><p>坏蛋黑客们最常干的一类事，就是登录你的账号，盗取你的信息。如果登录的是你银行账号，说不定会把你的存款全都偷走，是不是很可恶？</p><p>那黑客是怎么入侵别人系统的呢？最简单的入侵方法，叫做暴力破解——说白了就是拿字母和数字一个个去试。</p><p>你有没有想过，自己的密码有多安全吗？</p><figure><img src="/assets/image-20250425225618346-6gFZMbgs.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>现代计算机可以每秒钟尝试数百万组密码，如果你用的是简单的6位纯数字，比如“123456”，那对计算机来说就像是玩游戏一样轻松破解。<strong>几乎在你眨眼的一瞬间</strong>，你的密码就已经“破防”了。</p><p>这个地方做个补充：假如是纯数字组成的<strong>6位密码</strong>，理论上只有<strong>100万种</strong>可能性。所以对于现代计算机，只要眨眼即可破解纯数字密码。</p><p>但如果你用的是<strong>6位字母和数字组合</strong>呢，黑客也只需要<strong>5秒钟</strong>左右就能破解。当然了，你要是用<strong>12位的字母和数字组合</strong>，计算机就得花上<strong>几千年</strong>时间才能破解，这几乎是不可能的。</p><p>另外，黑客破解密码的时候，还有一个密码库，里面记录着特别常见的密码，什么123456789，abcd1234，这一类的密码虽然也比较长，但黑客破解的时候会优先尝试这些密码，破解它们也用不了1秒钟时间，所以这样的密码最好也不要用。</p><figure><img src="/assets/image-20250425232223227-BXBh5MRx.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20250425231814661-BuufE6U4.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>当然了，对于暴力破解，很多公司都有应对措施。比如说银行吧，虽然银行卡密码只有6位数，黑客眨眼间就能破解，但只要你的账号<strong>连续输错3次或者5次</strong>密码，银行就会发现异常，把你的账户锁住，必须你本人去才可以解锁。</p><p>还有苹果手机的开机密码，如果总是输错，手机就会<strong>锁定</strong>一段时间。要是再输错，这个锁定时间就会增加时间，这样一来，黑客就没法通过暴力破解的方式入侵了。</p><figure><img src="/assets/image-20250425232414262-Dc8U0tKl.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>所以，第一个保护你的秘诀就是：</p><p>🛡️ <strong>设置复杂的密码</strong>——长度要尽可能长，字母（最好有大小写）+数字+符号混搭起来，这样黑客的暴力破解就无效了。</p><p>简单来说，<strong>越复杂，越安全</strong>。别嫌麻烦，这是你数字身份的第一道防线！</p><h2 id="_2-第二招-别在每扇门上用同一把钥匙" tabindex="-1"><a class="header-anchor" href="#_2-第二招-别在每扇门上用同一把钥匙"><span>2. 第二招：别在每扇门上用同一把钥匙</span></a></h2><p>当然了，除了一个一个试，黑客还有其他破解方法。</p><p>很多人喜欢在所有平台用一个账号密码——记起来方便，但这就像你家、你朋友家、你保险柜……全部用一把钥匙。如果这把钥匙被偷了，所有“门”就都不安全了。</p><p>而黑客最常干的一件事就是：攻破一个小网站的数据库，拿到里面的用户账号和密码，再去尝试登录其他更重要的网站，比如银行、微信等。<strong>如果密码都一样，风险可就大了。</strong></p><p>为什么是小网站？因为：一些小公司因为技术有限，系统安全等级很低，黑客可以轻松入侵他们的数据库，直接盗取你的账号密码。</p><figure><img src="/assets/image-20250425234446512-DAeLbWE3.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>所以，第二个守护秘籍是：</p><p>🔐 <strong>重要账号（比如银行、支付平台）要用一套独立的密码</strong>，其他普通注册网站，可以共用一组不那么敏感的密码。这样，就算“小门”被攻破，“大门”也依然坚固。当然最好还是：<strong>不要在所有的平台用同一个账号密码</strong>。</p><p>如果你怕账号密码太多了记不住，我教你两个方法：</p><ul><li><p><strong>方法一</strong>：你可以只记两组账号密码，像银行、微信等等和金钱有关的平台，用一组账号密码，这些平台安全级别比较高，黑客不容易入侵。其他不重要的平台，用另一套账号密码注册，就算是这些账号密码泄露了，也不会对你造成太大影响。</p></li><li><p><strong>方法二</strong>：我自己比较常用的，就是：每个网站的开头密码相同，比如 “bornforthis0502”。此时我们要针对不同网站进行不同层度的加强和设定，例如：</p><ul><li>在谷歌网站，那就设置：<code>bornforthis0502Google</code>（当然，你也可以加点：<code>bornforthis0502Google.</code>）；</li><li>在 AI悦创网站，那就设置：<code>bornforthis0502Aiyuechuang</code>；</li><li>在 DeepSeek 网站，那就设置：<code>bornforthis0502Dk</code>、<code>bornforthis0502DeepSeek</code>；</li><li>……</li></ul><p>到这，你应该就知道方法设定密码的逻辑了。这样比较方便记忆，不过你还是要在构建密码的时候多花一点心思。</p></li></ul><h2 id="_3-第三招-链接再诱人-也要长个心眼" tabindex="-1"><a class="header-anchor" href="#_3-第三招-链接再诱人-也要长个心眼"><span>3. 第三招：链接再诱人，也要长个心眼</span></a></h2><figure><img src="/assets/image-20250425234729464-BFGfN3zx.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>有些黑客不会直接攻击系统，而是通过“钓鱼”让你自己把信息乖乖交出去。</p><p>他们会给你发一封邮件或者短信，说你的账户有问题、密码泄露了，让你赶快点击链接修改。链接看起来很像真的，但实际上是伪装的网站——你一旦在上面输入账号密码，你的所有操作都会被记录下来，就相当于主动把钥匙（银行卡卡号和密码）交给了小偷（黑客）。</p><p>所以第三个秘诀就是：</p><p>🚫 <strong>如果要修改账号密码，务必通过官方网站或官方 App 进行</strong>，不要随便点击邮件或短信里的可疑链接。</p><h2 id="_4-人工智能-也有-看不见-的漏洞" tabindex="-1"><a class="header-anchor" href="#_4-人工智能-也有-看不见-的漏洞"><span>4. 人工智能，也有“看不见”的漏洞？</span></a></h2><p>很多人觉得，随着人脸识别、指纹解锁这些技术的普及，我们终于安全了——对黑客来说，这两样东西可不好偷了，总不能偷走你的脸或者手吧？</p><p>但故事并没有这么简单，黑客们可都是找漏洞高手。只要安全系统里有漏洞，他们就能钻上空子。</p><p>举个例子：</p><figure><img src="/assets/image-20250425235034299-CAffJfnL.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>有黑客发现，只要在一张图片上加入人眼看不出来的“扰动图案”，就能让图像识别系统“看错人”。明明是熊猫的照片，AI 却识别成了长臂猿！上头我把扰动图案明显化，这就是图像识别算法上的漏洞。</p><figure><img src="/assets/image-20250426082127182-BPH8YPPE.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>再比如，一个人只要在衣服上贴一张特殊图案，AI 摄像头可能就完全“看不见”这个人——像是贴了隐身符。</p><p>这说明，即便是最先进的人工智能，也可能被“算计”。</p><p>想象一下：要是在银行金库装好多好多摄像头，这些摄像头能够识别画面里的物体，只要发现了人类，就发出报警。这时候，只要贴上这么一张图片，就好像贴了隐身符一样，就算你把金库搬个金光摄像头也不会有任何反应。</p><p>听到这是不是有点担心，即便是人工智能技术都有漏洞，那在黑客面前，我们要怎么办呢？</p><h2 id="_5-不是所有黑客都是反派-有一种叫-白帽子" tabindex="-1"><a class="header-anchor" href="#_5-不是所有黑客都是反派-有一种叫-白帽子"><span>5. 不是所有黑客都是反派：有一种叫“白帽子”</span></a></h2><p>别太担心，其实网络安全的战场上，有一批和黑客同样聪明，但站在我们这边的高手——他们叫做<strong>白帽黑客</strong>。</p><p>这些人专门负责寻找系统漏洞、测试网站安全，甚至有公司会专门请他们“来攻破自己”，以便及时修补系统的薄弱之处。还有些白帽子们参与国际网络安全竞赛，为的是提升防御能力、守护数据安全。</p><p>你或许想不到，那些研究如何欺骗 AI 的科学家、破解系统只是为了找漏洞的高手，<strong>其实是在帮我们守护数字世界的边界</strong>。</p><p>也许某一天，你也会变成一个技术高超的程序员，成为“正义阵营”的一员，用技术守护大家的数字生活。那就是属于你的“黑客梦”。</p>`,57)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};